using System.Globalization;
using System.Text.RegularExpressions;
using PropStruct.Tests.Harness;
using Xunit;

namespace PropStruct.Particle.Tests;

/// <summary>
/// The site list of <c>ExactConstants</c> at this node (<c>BOOT.md</c>, "## Corrected model"):
/// <c>ExactConstantLiterals.generated.txt</c> is the list of every literal approximating pi or
/// 1/3 in the four line-map ranges of the Fortran, generated by <c>scan-exact-constants.py</c>
/// and checked by regeneration; <c>ExactConstantSites.txt</c> is the hand-written mapping, one
/// row per listed literal, to the C# site that is pi under the flag, to <c>not ported</c>, to
/// <c>unchanged: &lt;reason&gt;</c> or to <c>BridgeFrustum</c>. <see cref="Disagreements"/> checks
/// the two files and <c>Attempt.cs</c> both ways; the tests prove it red on a synthetic break of
/// each file and, for the scan, on a literal added to a scratch copy of the original's source
/// (<c>Category=Legacy</c>), and right on the real files.
/// </summary>
public class ExactConstantSiteTests
{
    private static readonly string[] Identifiers = ["spherePiOver6", "fourPi"];

    private static readonly string GeneratedPath = RepositoryPaths.Resolve("src", "Particle", "ExactConstantLiterals.generated.txt");
    private static readonly string MappingPath = RepositoryPaths.Resolve("src", "Particle", "ExactConstantSites.txt");
    private static readonly string AttemptPath = RepositoryPaths.Resolve("src", "Particle", "Attempt.cs");

    private static readonly Regex CitationPattern = new(@"\((\d+)\)", RegexOptions.Compiled);

    private readonly record struct Site(int Line, string Literal);

    private static List<Site> ParseSites(string text)
    {
        var sites = new List<Site>();
        foreach (var cells in Rows(text))
        {
            sites.Add(new Site(int.Parse(cells[0], CultureInfo.InvariantCulture), cells[1]));
        }

        return sites;
    }

    private static IEnumerable<string[]> Rows(string text)
    {
        foreach (var rawLine in text.Split('\n'))
        {
            var line = rawLine.TrimEnd('\r').Trim();
            if (line.Length == 0 || line[0] == '#')
            {
                continue;
            }

            var cells = line.Split('|', 3).Select(cell => cell.Trim()).ToArray();
            Assert.True(cells.Length == 3, $"malformed row: {line}");
            yield return cells;
        }
    }

    /// <summary>
    /// Every disagreement between the generated list, the mapping and <c>Attempt.cs</c>: a
    /// listed literal without a mapping row, a mapping row without a listed literal, a
    /// disposition outside the vocabulary, an <c>exact</c> row whose Fortran line is cited on
    /// no line of <c>Attempt.cs</c> using its identifier, and a line of <c>Attempt.cs</c> using
    /// an identifier that cites no Fortran line mapped to it.
    /// </summary>
    private static List<string> Disagreements(string generatedText, string mappingText, string attemptText)
    {
        var problems = new List<string>();
        var listed = ParseSites(generatedText);
        var mapped = Rows(mappingText)
            .Select(cells => (Site: new Site(int.Parse(cells[0], CultureInfo.InvariantCulture), cells[1]), Disposition: cells[2]))
            .ToList();

        foreach (var site in listed.Where(site => mapped.All(row => row.Site != site)))
        {
            problems.Add($"Fortran line {site.Line}, literal {site.Literal}: listed by the scan, no row in ExactConstantSites.txt.");
        }

        foreach (var row in mapped.Where(row => !listed.Contains(row.Site)))
        {
            problems.Add($"Fortran line {row.Site.Line}, literal {row.Site.Literal}: a row of ExactConstantSites.txt that the scan does not list.");
        }

        foreach (var duplicate in mapped.GroupBy(row => row.Site).Where(group => group.Count() > 1))
        {
            problems.Add($"Fortran line {duplicate.Key.Line}, literal {duplicate.Key.Literal}: more than one row in ExactConstantSites.txt.");
        }

        foreach (var (site, disposition) in mapped)
        {
            if (!IsKnownDisposition(disposition))
            {
                problems.Add($"Fortran line {site.Line}: the disposition '{disposition}' is not exact: <identifier>, not ported: <why>, unchanged: <why> or BridgeFrustum.");
            }
        }

        var attemptLines = attemptText.Split('\n');
        foreach (var (site, disposition) in mapped.Where(row => row.Disposition.StartsWith("exact: ", StringComparison.Ordinal)))
        {
            var identifier = disposition["exact: ".Length..];
            if (!attemptLines.Any(line => Cites(line, site.Line) && line.Contains(identifier, StringComparison.Ordinal)))
            {
                problems.Add($"Fortran line {site.Line}: mapped to {identifier}, and no line of Attempt.cs citing ({site.Line}) uses it.");
            }
        }

        foreach (var identifier in Identifiers)
        {
            foreach (var line in attemptLines.Where(line => UsesIdentifier(line, identifier)))
            {
                var cited = CitedLines(line);
                if (!cited.Any(number => mapped.Any(row => row.Site.Line == number && row.Disposition == $"exact: {identifier}")))
                {
                    problems.Add($"Attempt.cs uses {identifier} on a line citing no Fortran line mapped to it: {line.Trim()}");
                }
            }
        }

        return problems;
    }

    private static bool IsKnownDisposition(string disposition)
        => disposition.StartsWith("exact: ", StringComparison.Ordinal) && Identifiers.Contains(disposition["exact: ".Length..])
        || disposition.StartsWith("not ported: ", StringComparison.Ordinal) && disposition.Length > "not ported: ".Length
        || disposition.StartsWith("unchanged: ", StringComparison.Ordinal) && disposition.Length > "unchanged: ".Length
        || disposition == "BridgeFrustum";

    // A use, not the declaration `var <identifier> = ...` and not a comment-only line.
    private static bool UsesIdentifier(string line, string identifier)
        => line.Contains(identifier, StringComparison.Ordinal)
        && !line.TrimStart().StartsWith("//", StringComparison.Ordinal)
        && !line.Contains($"var {identifier} =", StringComparison.Ordinal);

    private static bool Cites(string line, int fortranLine) => CitedLines(line).Contains(fortranLine);

    private static List<int> CitedLines(string line)
    {
        var commentStart = line.IndexOf("//", StringComparison.Ordinal);
        return commentStart < 0
            ? []
            : CitationPattern.Matches(line[commentStart..]).Select(match => int.Parse(match.Groups[1].Value, CultureInfo.InvariantCulture)).ToList();
    }

    /// <summary>Right on the real files: the list, the mapping and Attempt.cs agree.</summary>
    [Fact]
    public void TheCommittedListTheMappingAndAttemptAgree()
    {
        var problems = Disagreements(File.ReadAllText(GeneratedPath), File.ReadAllText(MappingPath), File.ReadAllText(AttemptPath));

        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
    }

    /// <summary>
    /// Red on a literal the scan lists and the mapping does not know (the scan's output
    /// grown by one row), and on a mapping row removed.
    /// </summary>
    [Fact]
    public void ARowMissingFromEitherFileIsReported()
    {
        var generated = File.ReadAllText(GeneratedPath);
        var mapping = File.ReadAllText(MappingPath);
        var attempt = File.ReadAllText(AttemptPath);

        var grown = generated + "447 | 3.14159 | 1\n";
        Assert.Contains(Disagreements(grown, mapping, attempt), problem => problem.StartsWith("Fortran line 447", StringComparison.Ordinal));

        var shrunk = string.Join('\n', mapping.Split('\n').Where(line => !line.StartsWith("524 |", StringComparison.Ordinal)));
        Assert.Contains(Disagreements(generated, shrunk, attempt), problem => problem.StartsWith("Fortran line 524", StringComparison.Ordinal));

        var invented = mapping + "448 | 3.14159 | exact: fourPi\n";
        Assert.Contains(Disagreements(generated, invented, attempt), problem => problem.StartsWith("Fortran line 448", StringComparison.Ordinal));

        var misspelled = mapping.Replace("469 | 3.14159 | exact: spherePiOver6", "469 | 3.14159 | exact: nothing", StringComparison.Ordinal);
        Assert.Contains(Disagreements(generated, misspelled, attempt), problem => problem.Contains("469", StringComparison.Ordinal));
    }

    /// <summary>
    /// Red on <c>Attempt.cs</c> both ways: a Fortran line mapped to an identifier that no line
    /// citing it uses (a site reverted to the literal), and a use of the identifier that cites
    /// no line mapped to it (a site added).
    /// </summary>
    [Fact]
    public void ASiteMissingFromAttemptOrAddedToItIsReported()
    {
        var generated = File.ReadAllText(GeneratedPath);
        var mapping = File.ReadAllText(MappingPath);
        var attempt = File.ReadAllText(AttemptPath);

        var reverted = attempt.Replace("spherePiOver6 * rk * rk * rk; // VKS (677)", "3.14159 / 6.0 * rk * rk * rk; // VKS (677)", StringComparison.Ordinal);
        Assert.NotEqual(attempt, reverted);
        Assert.Contains(Disagreements(generated, mapping, reverted), problem => problem.StartsWith("Fortran line 677", StringComparison.Ordinal));

        var added = attempt.Replace("var rk = aa;    // RK = AA (672)", "var rk = aa * spherePiOver6;    // RK = AA (672)", StringComparison.Ordinal);
        Assert.NotEqual(attempt, added);
        Assert.Contains(Disagreements(generated, mapping, added), problem => problem.StartsWith("Attempt.cs uses spherePiOver6", StringComparison.Ordinal));
    }

    // Reads the Fortran source, which lies outside the repository (tools/legacy): Category=Legacy.
    [Fact]
    [Trait("Category", "Legacy")]
    public void ScanReproducesTheCommittedListOnRegeneration()
        => PythonScript.RequireSuccess(Path.Combine("src", "Particle", "scan-exact-constants.py"), "verify");

    /// <summary>
    /// Red on a literal added to a scratch copy of the source: the scan of the copy lists the
    /// added literal, the list is not the committed one, and the mapping has no row for it.
    /// Right: the scan of an untouched copy is the committed list byte for byte.
    /// </summary>
    [Fact]
    [Trait("Category", "Legacy")]
    public void AScratchCopyWithALiteralAddedIsReportedAndAnUntouchedCopyIsNot()
    {
        var path = PythonScript.Run(RepositoryPaths.Root, Path.Combine("tools", "legacy", "legacy.py"), ["path", "PropStructv3.for.txt"]);
        Assert.True(path.ExitCode == 0, path.StandardError);
        var sourceLines = File.ReadAllLines(path.StandardOutput.Trim());

        var scratch = Directory.CreateTempSubdirectory("propstruct_exact_constants_");
        try
        {
            var untouched = Scan(scratch.FullName, "untouched.txt", sourceLines);
            Assert.Equal(File.ReadAllText(GeneratedPath), untouched);

            // Line 440 is `Vdok_loc = 0.` inside the first range: appending a pi literal adds a site.
            var edited = (string[])sourceLines.Clone();
            edited[439] += "+3.14159";
            var added = Scan(scratch.FullName, "added.txt", edited);
            Assert.NotEqual(File.ReadAllText(GeneratedPath), added);
            Assert.Contains(
                Disagreements(added, File.ReadAllText(MappingPath), File.ReadAllText(AttemptPath)),
                problem => problem.StartsWith("Fortran line 440", StringComparison.Ordinal));
        }
        finally
        {
            scratch.Delete(recursive: true);
        }
    }

    private static string Scan(string directory, string name, string[] sourceLines)
    {
        var copy = Path.Combine(directory, name);
        File.WriteAllLines(copy, sourceLines);
        var run = PythonScript.Run(RepositoryPaths.Root, Path.Combine("src", "Particle", "scan-exact-constants.py"), ["scan", "--source", copy]);
        Assert.True(run.ExitCode == 0, run.StandardError);
        return run.StandardOutput.Replace("\r\n", "\n", StringComparison.Ordinal);
    }
}
